def generate_primes(start, end):
    """
    Generate all prime numbers in the range from start to end (both inclusive) 
    """
    def is_prime(n):
        """
        Check if a number is prime
        """
        if n <= 1:
            return False
        for i in range(2, n):
            if n % i == 0:
                return False
        return True    

    prime_numbers = []

    for n in range(start, end + 1):
        if is_prime(n):
            prime_numbers.append(n)

    return prime_numbers

