def product_of_others(a, b):
    n = len(a)
    m = len(b)

    if n != m:
        raise ValueError("The arrays a and b should be of the same length")

    if n == 0:
        return []

    # Compute the prefix product array for a
    prefix_a = [1]*n
    for i in range(1, n):
        prefix_a[i] = prefix_a[i-1]*a[i-1]

    # Compute the suffix product array for b
    suffix_b = [1]*n
    for i in range(n-2, -1, -1):
        suffix_b[i] = suffix_b[i+1]*b[i+1]

    # Compute the product array c
    c = [1]*n
    for i in range(n):
        c[i] = prefix_a[i]*suffix_b[i]

    return c

